//! The Python scaffold: one component's uv project, served to
//! angzarr-embedded as a child process through angzarr-client-python's
//! harness (`angzarr_client.child`). The component is an aggregate or a
//! process manager of a domain, a policy, or a projector over one or
//! more source domains (decision 14.50).
//!
//! The project is split so that the user never edits a generated file and
//! a run never rewrites the user's (decision item S):
//!
//! - written once, the user's ([`Owner::User`]): `pyproject.toml`, the
//!   package's `__init__.py`, its `__main__.py` (the composition root: it
//!   builds the logic, its dependencies its constructor's arguments, and
//!   runs it with `_gen.main.run`), `tests/__init__.py`, and the logic's
//!   implementation (`logic_impl.py`, subclassing the generated interface,
//!   every method `raise NotImplementedError  # TODO`);
//! - rewritten on every run, the CLI's ([`Owner::Generated`]), each opening
//!   with the generated marker and all of it under the package's `_gen`
//!   (the one path every gate excludes): `domain.py` (the messages as
//!   frozen dataclasses and enums, no protobuf), `logic.py` (the interface:
//!   an `abc.ABC` of the required methods, and the optional refusal
//!   callbacks' reference `Protocol`), `main.py` (the child's host, given
//!   the logic), `_version.py`, `_descriptor.py`, the packages'
//!   `__init__.py`, the dispatch, which converts the router binding's wire
//!   calls to calls on the logic, and buf's message types; and the
//!   project's `buf.gen.yaml`.
//!
//! Inside `_gen` every import of the project's own is relative, and nothing
//! there imports a user module: the user's `__main__.py` hands `_gen` the
//! logic. Every generated file stands on angzarr-client-python's public API
//! only (`angzarr_client.router`'s dispatch tables,
//! `ComponentHost.add_<kind>`, `run_child`). A change to the harness or to
//! the scaffold touches only generated files.
//!
//! One module per artefact: [`domain`] (`domain.py`), [`convert`] (the
//! wire converters), [`dispatch`], [`logic`] (the interface and its
//! implementation), [`project`] (`main.py`, `__main__.py`, `pyproject.toml`,
//! `buf.gen.yaml`, `_descriptor.py`), [`complete`] (`--missing`), and
//! [`layout`], black's line layout they share.

mod complete;
mod convert;
mod dispatch;
mod domain;
mod layout;
mod logic;
mod project;

use std::collections::BTreeSet;

use prost_reflect::{EnumDescriptor, Kind, MessageDescriptor};

use crate::common::{Arm, handed_refusals, local_name, snake, wire_name};
use crate::error::{CodegenError, ProtoError, UseError};
use crate::model::{self, ALL_KINDS, Component, ComponentKind, Input};
use crate::scaffold::{Owner, ScaffoldFile, Translate, selected};
use dispatch::dispatch;
use domain::domain_py;
use logic::{implementation, interface};
use project::{buf_gen, descriptor_py, dunder_main, main_py, proto_paths, pyproject};

pub(crate) use complete::complete;
pub use project::{python_reroots, reroot_python};

/// The angzarr Python package (angzarr-client-python) the scaffold depends
/// on, pinned by commit: every project this CLI scaffolds gets this one.
pub const CLIENT_PYTHON_REV: &str = "dbec93ff2036f2fbcb37d1582f08d83977276622";
/// Where [`CLIENT_PYTHON_REV`] is fetched from.
pub const CLIENT_PYTHON_GIT: &str = "https://github.com/angzarr-io/angzarr-client-python";

/// The proto packages angzarr-client-python ships generated, imported from
/// `angzarr_client.proto` and never generated into a project: the four of
/// decision 14.64 (core, the component contract and both transports) and
/// sererr.
const FRAMEWORK_PACKAGES: &[&str] = &[
    "io.angzarr.v1",
    "io.angzarr.component.v1",
    "io.angzarr.transport.embedded.v1",
    "io.angzarr.transport.distributed.v1",
    "sererr.v1",
];
/// Black's line width, which the generated Python is laid out to.
const WIDTH: usize = 88;
/// The header of every generated file: the generated marker
/// ([`crate::GENERATED_MARKER`]), which tools and the scaffold's own write
/// path read.
pub(crate) const GENERATED: &str = concat!(
    "# @generated by angzarr-cli ",
    env!("CARGO_PKG_VERSION"),
    ". DO NOT EDIT.\n"
);
/// Where the generated modules go, under the package: the one path every
/// gate of a project excludes.
const GEN: &str = "_gen";
/// The names `domain.py` gives the harness's types beyond the shared
/// [`model::RESERVED`]: a reaction's and a projection's context.
const PYTHON_RESERVED: &[&str] = &["PageContext"];

/// Where `buf generate` reads the domain's protos from.
#[derive(Clone, PartialEq, Eq, Debug)]
pub enum ProtoInput {
    /// A git repository at a revision, the protos under its `proto`, as
    /// angzarr-project lays them out.
    Git { url: String, rev: String },
    /// A directory, relative to the project root (where buf runs) or
    /// absolute.
    Directory(String),
}

/// One Python component's project.
#[derive(Clone, PartialEq, Eq, Debug)]
pub struct PythonApp {
    /// What the project serves: a domain (its aggregate's or process
    /// manager's, e.g. `player`), or a component's name in an application
    /// (`component_name`, else its kind's default: `policy-table-player`,
    /// `projector-wallet-table-ledger`). The package is `angzarr_<domain>`,
    /// the distribution and its script `angzarr-<domain>`.
    pub domain: String,
    pub protos: ProtoInput,
    /// The build version the component reports as its rules_version.
    pub rules_version: String,
}

impl PythonApp {
    fn package(&self) -> String {
        format!("angzarr_{}", self.domain.replace('-', "_"))
    }

    fn script(&self) -> String {
        format!("angzarr-{}", self.domain.replace('_', "-"))
    }
}

/// One component as the Python scaffold emits it.
struct Unit {
    component: Component,
    /// Its name in an application: its `component_name`, else its kind's
    /// default.
    name: String,
    /// A policy's target's commands: what its reactions send as commands.
    commands: Vec<MessageDescriptor>,
    /// A policy's target's facts: what its reactions send as facts, the
    /// arm the target declares (decision 14.69).
    sent_facts: Vec<MessageDescriptor>,
    /// A projector's source domains.
    sources: Vec<String>,
    /// The commands whose refusal reaches the unit: a domain's, each
    /// command a policy it sources sends that declares a `refuses` type (the
    /// pass-through `CommandRefused`, decision 14.31; only a typed refusal
    /// is handed over, decision 14.73); a policy's, each command it sends
    /// when its source takes facts to translate a refusal into. Whatever `--translate`
    /// selects: the generated files are the same either way.
    refusable: Vec<Refusable>,
    /// The refusal switch's selections touching the unit, each a command's
    /// full name and the fact it translates into: a policy's own, which its
    /// logic translates; a domain's, the ones its policies translate, which
    /// its logic is not handed as `CommandRefused`.
    translated: Vec<(String, MessageDescriptor)>,
    /// A policy's source's facts: what a translating callback returns.
    facts: Vec<MessageDescriptor>,
    /// The refused commands whose callback `--on-refused` selects, by full
    /// name: written into the user's implementation even when it exists.
    on_refused: Vec<String>,
}

/// A command whose refusal reaches a unit, and the typed refusals it
/// refuses with.
struct Refusable {
    command: MessageDescriptor,
    refuses: Vec<MessageDescriptor>,
}

impl Refusable {
    fn of(input: &Input) -> Self {
        Refusable {
            command: input.message.clone(),
            refuses: input.refuses.clone(),
        }
    }
}

impl Unit {
    fn kind(&self) -> ComponentKind {
        self.component.kind
    }

    /// A domain: an aggregate or a process manager, deciding inputs and
    /// folding its events.
    fn is_domain(&self) -> bool {
        self.kind().is_domain()
    }
}

/// The project of `app.domain`: the component of that domain, or of that
/// name, declared in `files`, as the files listed in the module doc. Paths
/// are relative to the project root.
pub fn scaffold_python(
    descriptor_set: &[u8],
    files: &[&str],
    app: &PythonApp,
    translate: &[Translate],
    on_refused: &[String],
) -> Result<Vec<ScaffoldFile>, CodegenError> {
    let pool = crate::scaffold::checked_pool(descriptor_set, translate)?;
    let components: Vec<Component> = model::components(descriptor_set, files, ALL_KINDS)?
        .into_iter()
        .filter(|c| c.domain == app.domain || c.component_name == app.domain)
        .collect();
    if components.is_empty() {
        return Err(UseError::PythonNoDomain {
            domain: app.domain.clone(),
        }
        .into());
    }
    let units = components
        .into_iter()
        .map(|c| unit(c, &pool, translate, on_refused))
        .collect::<Result<Vec<_>, _>>()?;
    refuse_python_names(&units)?;
    let project = Project::new(app, &units);
    let mut out = project.files(descriptor_set, files)?;
    out.extend(units.iter().flat_map(|unit| project.unit_files(unit)));
    out.extend(project.package_markers());
    out.sort_by(|a, b| a.path.cmp(&b.path));
    Ok(crate::headed_files(out))
}

/// Refuses a type the units reach whose local name the generated domain
/// layer, or Python, reserves.
fn refuse_python_names(units: &[Unit]) -> Result<(), ProtoError> {
    for unit in units {
        let (messages, enums) = reached(unit);
        let names: Vec<(&str, String)> = messages
            .iter()
            .map(|m| (m.full_name(), local_name(m.full_name(), m.package_name())))
            .chain(
                enums
                    .iter()
                    .map(|e| (e.full_name(), local_name(e.full_name(), e.package_name()))),
            )
            .collect();
        model::refuse_reserved(names.iter().cloned())?;
        if let Some((full, local)) = names
            .into_iter()
            .find(|(_, local)| PYTHON_RESERVED.contains(&local.as_str()))
        {
            return Err(ProtoError::ReservedName {
                message: full.to_string(),
                name: local,
            });
        }
    }
    Ok(())
}

/// The project being written: its app, its units (the first the one it
/// is named for) and what every file of it shares.
struct Project<'a> {
    app: &'a PythonApp,
    units: &'a [Unit],
    /// What it serves, for the docs ([`served`]).
    served: String,
    /// Its package's directory, `src/<package>`.
    src: String,
    /// Its generated package's directory, `src/<package>/_gen`.
    gen_dir: String,
}

impl<'a> Project<'a> {
    fn new(app: &'a PythonApp, units: &'a [Unit]) -> Project<'a> {
        let src = format!("src/{}", app.package());
        Project {
            app,
            units,
            served: served(app, &units[0]),
            gen_dir: format!("{src}/{GEN}"),
            src,
        }
    }

    /// A file of the project, of `unit`'s component.
    fn file(&self, unit: &Unit, path: String, source: String, owner: Owner) -> ScaffoldFile {
        ScaffoldFile::new(
            unit.component.anchor.full_name().to_string(),
            path,
            source,
            owner,
        )
    }

    /// The files of the project as a whole: its manifest, buf config, entry
    /// points and descriptor module; and the files an earlier scaffold
    /// wrote beside the user's, which this one writes under `_gen`
    /// ([`Owner::Obsolete`]).
    fn files(
        &self,
        descriptor_set: &[u8],
        files: &[&str],
    ) -> Result<Vec<ScaffoldFile>, CodegenError> {
        let (app, served, src, units) = (self.app, self.served.as_str(), &self.src, self.units);
        let gen_dir = &self.gen_dir;
        let file =
            |path: String, source: String, owner: Owner| self.file(&units[0], path, source, owner);
        let mut out = vec![
            file(
                "pyproject.toml".to_string(),
                pyproject(app, served, units),
                Owner::User,
            ),
            file(
                "buf.gen.yaml".to_string(),
                buf_gen(app, served, units),
                Owner::Generated,
            ),
            file(format!("{src}/__init__.py"), String::new(), Owner::User),
            file(
                format!("{src}/__main__.py"),
                dunder_main(app, served, units),
                Owner::User,
            ),
            file(
                format!("{gen_dir}/_version.py"),
                format!(
                    "{GENERATED}\"\"\"The build version {served} reports as its rules_version.\"\"\"\n\n__version__ = {:?}\n",
                    app.rules_version
                ),
                Owner::Generated,
            ),
            file(
                format!("{gen_dir}/main.py"),
                main_py(app, served, units),
                Owner::Generated,
            ),
            file(
                format!("{gen_dir}/_descriptor.py"),
                descriptor_py(app, served, descriptor_set, files, &units[0])?,
                Owner::Generated,
            ),
            file("tests/__init__.py".to_string(), String::new(), Owner::User),
        ];
        // buf's message types, written after these: each module's pb2 and
        // its stub.
        for proto in proto_paths(units) {
            let stem = proto.trim_end_matches(".proto");
            for ext in ["py", "pyi"] {
                out.push(file(
                    format!("{gen_dir}/{stem}_pb2.{ext}"),
                    String::new(),
                    Owner::External,
                ));
            }
        }
        for moved in ["domain", "logic", "main", "_version", "_descriptor"] {
            out.push(file(
                format!("{src}/{moved}.py"),
                String::new(),
                Owner::Obsolete,
            ));
        }
        Ok(out)
    }

    /// A unit's own files: its logic interface and implementation, its
    /// plain types and its dispatch.
    fn unit_files(&self, unit: &Unit) -> Vec<ScaffoldFile> {
        let (app, src, gen_dir) = (self.app, &self.src, &self.gen_dir);
        let dir = module_dir(&unit.component.anchor);
        let stem = snake(&unit.component.name);
        let file =
            |path: String, source: String, owner: Owner| self.file(unit, path, source, owner);
        let (source, optional, selected) = implementation(app, unit);
        let mut implementation = file(format!("{src}/logic_impl.py"), source, Owner::User);
        implementation.optional = optional;
        implementation.selected = selected;
        vec![
            file(
                format!("{gen_dir}/logic.py"),
                interface(app, unit),
                Owner::Generated,
            ),
            implementation,
            file(
                format!("{gen_dir}/domain.py"),
                domain_py(&self.served, unit),
                Owner::Generated,
            ),
            file(
                format!("{gen_dir}/{dir}/{stem}_angzarr.py"),
                dispatch(app, unit),
                Owner::Generated,
            ),
        ]
    }

    /// The `__init__.py` of every package the dispatches are in: `_gen` and
    /// each directory down to a unit's module, each once.
    fn package_markers(&self) -> Vec<ScaffoldFile> {
        let mut packages = BTreeSet::new();
        for unit in self.units {
            let mut path = GEN.to_string();
            packages.insert(path.clone());
            for part in module_dir(&unit.component.anchor).split('/') {
                path = format!("{path}/{part}");
                packages.insert(path.clone());
            }
        }
        packages
            .into_iter()
            .map(|dir| {
                let path = format!("{}/{dir}/__init__.py", self.src);
                self.file(
                    &self.units[0],
                    path,
                    GENERATED.to_string(),
                    Owner::Generated,
                )
            })
            .collect()
    }
}

/// `component` with what its kind needs beside it, from the descriptor
/// set's `pool`: a policy's target's commands (refused when no aggregate or
/// process manager of the set owns its `output_domain`) and, when its
/// source takes facts, those facts and the commands it may translate the
/// refusal of; a domain's commands its policies send, refusable back to
/// it; a projector's sources; and the `translate` selections touching it.
fn unit(
    component: Component,
    pool: &[Component],
    translate: &[Translate],
    on_refused: &[String],
) -> Result<Unit, CodegenError> {
    let owner = |domain: &str| model::owner(pool, domain);
    let fact_of = |selection: &Translate| {
        owner_input(pool, &selection.fact).map(|f| (selection.command.clone(), f))
    };
    let mut commands = Vec::new();
    let mut sent_facts = Vec::new();
    let mut refusable = Vec::new();
    let mut translated = Vec::new();
    let mut facts = Vec::new();
    match component.kind {
        ComponentKind::Policy => {
            let target = component.target(pool)?;
            let sent: Vec<&Input> = target
                .inputs
                .iter()
                .filter(|i| Arm::of(i) == Arm::Command)
                .collect();
            commands = sent.iter().map(|i| i.message.clone()).collect();
            sent_facts = target
                .inputs
                .iter()
                .filter(|i| Arm::of(i) == Arm::Fact)
                .map(|i| i.message.clone())
                .collect();
            if let Some(source) = owner(&component.input_domain) {
                facts = source
                    .inputs
                    .iter()
                    .filter(|i| i.fact)
                    .map(|i| i.message.clone())
                    .collect();
            }
            if !facts.is_empty() {
                refusable = sent.into_iter().map(Refusable::of).collect();
            }
            translated = selected(translate, &component)
                .filter_map(fact_of)
                .collect();
        }
        ComponentKind::Aggregate | ComponentKind::ProcessManager => {
            for policy in pool
                .iter()
                .filter(|p| p.kind == ComponentKind::Policy && p.input_domain == component.domain)
            {
                let Some(target) = owner(&policy.output_domain) else {
                    continue;
                };
                for input in handed_refusals(target) {
                    if !refusable
                        .iter()
                        .any(|r: &Refusable| r.command == input.message)
                    {
                        refusable.push(Refusable::of(input));
                    }
                }
                translated.extend(selected(translate, policy).filter_map(fact_of));
            }
        }
        ComponentKind::Projector => {}
    }
    let sources = if component.kind == ComponentKind::Projector {
        component.sources.clone()
    } else {
        Vec::new()
    };
    Ok(Unit {
        name: component.component_name.clone(),
        component,
        commands,
        sent_facts,
        sources,
        refusable,
        translated,
        facts,
        on_refused: on_refused.to_vec(),
    })
}

/// The message of the input of some aggregate or process manager of
/// `pool` named `full_name`.
fn owner_input(pool: &[Component], full_name: &str) -> Option<MessageDescriptor> {
    pool.iter()
        .filter(|c| c.kind.is_domain())
        .find_map(|c| c.input(full_name))
        .map(|i| i.message.clone())
}

/// What the project serves, for its docs: `the player domain`, `the
/// policy-table-player policy`.
fn served(app: &PythonApp, unit: &Unit) -> String {
    match unit.kind() {
        ComponentKind::Aggregate | ComponentKind::ProcessManager => {
            format!("the {} domain", app.domain)
        }
        ComponentKind::Policy => format!("the {} policy", unit.name),
        ComponentKind::Projector => format!("the {} projector", unit.name),
    }
}

/// `served` with its first letter upper-cased.
fn capital(served: &str) -> String {
    let mut chars = served.chars();
    chars
        .next()
        .map(|c| c.to_ascii_uppercase().to_string() + chars.as_str())
        .unwrap_or_default()
}

/// `io/angzarr/examples/v1` for a message of `io/angzarr/examples/v1/x.proto`.
fn module_dir(message: &MessageDescriptor) -> String {
    let name = message.parent_file().name().to_string();
    name.rsplit_once('/')
        .map_or(String::new(), |(dir, _)| dir.to_string())
}

/// A message's pb2 module under `_gen`, by its parts: `io/angzarr/x.proto`
/// as `["io", "angzarr", "x_pb2"]`.
fn pb2_module(message: &MessageDescriptor) -> Vec<String> {
    let name = message.parent_file().name().to_string();
    let stem = name.trim_end_matches(".proto");
    format!("{stem}_pb2")
        .split('/')
        .map(str::to_string)
        .collect()
}

/// The relative import of `module` (its parts under `_gen`) from a module
/// of the package `from` (its parts under `_gen`): the `from` clause and the
/// name imported, `(".", "x_pb2")` beside it, `("..", "domain")` from one
/// package down.
fn relative(from: &[String], module: &[String]) -> (String, String) {
    let (parent, leaf) = module.split_at(module.len().saturating_sub(1));
    let common = from.iter().zip(parent).take_while(|(a, b)| a == b).count();
    let dots = ".".repeat(from.len() - common + 1);
    (
        format!("{dots}{}", parent[common..].join(".")),
        leaf.first().cloned().unwrap_or_default(),
    )
}

/// The relative path of `module` from a module of the package `from` (each
/// by its parts under `_gen`), to import a name from it: `..logic`.
fn relative_module(from: &[String], module: &[String]) -> String {
    let (clause, leaf) = relative(from, module);
    if clause.ends_with('.') {
        format!("{clause}{leaf}")
    } else {
        format!("{clause}.{leaf}")
    }
}

/// The package a unit's dispatch is in, by its parts under `_gen`.
fn dispatch_package(unit: &Unit) -> Vec<String> {
    module_dir(&unit.component.anchor)
        .split('/')
        .filter(|p| !p.is_empty())
        .map(str::to_string)
        .collect()
}

/// The pb2 alias the dispatch imports a message's module as: `_<stem>`.
fn alias(message: &MessageDescriptor) -> String {
    let name = message.parent_file().name().to_string();
    let stem = name
        .rsplit('/')
        .next()
        .unwrap_or(&name)
        .trim_end_matches(".proto");
    format!("_{stem}")
}

/// The messages the plain types start from: a domain's state, inputs,
/// what they emit and refuse, and its events; a policy's events and its
/// target's inputs, commands and facts; a projector's projection and its
/// events.
fn roots(unit: &Unit) -> Vec<MessageDescriptor> {
    let component = &unit.component;
    let mut roots = Vec::new();
    if component.kind != ComponentKind::Policy {
        roots.push(component.anchor.clone());
    }
    for input in &component.inputs {
        roots.push(input.message.clone());
        roots.extend(input.emits.iter().cloned());
        roots.extend(input.refuses.iter().cloned());
    }
    roots.extend(component.events.iter().cloned());
    roots.extend(unit.commands.iter().cloned());
    roots.extend(unit.sent_facts.iter().cloned());
    for refusable in &unit.refusable {
        roots.push(refusable.command.clone());
        roots.extend(refusable.refuses.iter().cloned());
    }
    roots.extend(unit.facts.iter().cloned());
    roots
}

/// A field's kind, a map's by its value.
fn element_kind(field: &prost_reflect::FieldDescriptor) -> Kind {
    match field.kind() {
        Kind::Message(entry) if entry.is_map_entry() => entry.map_entry_value_field().kind(),
        kind => kind,
    }
}

/// Every message and enum of the unit's plain types, every one its
/// [`roots`] reach, in the order they are reached, each once by its full
/// name (a policy's target commands are read from a pool of their own);
/// angzarr's own and google's excepted.
fn reached(unit: &Unit) -> (Vec<MessageDescriptor>, Vec<EnumDescriptor>) {
    let mut messages: Vec<MessageDescriptor> = Vec::new();
    let mut enums: Vec<EnumDescriptor> = Vec::new();
    let foreign =
        |package: &str| FRAMEWORK_PACKAGES.contains(&package) || package.starts_with("google.");
    let mut queue = roots(unit);
    let mut i = 0;
    while i < queue.len() {
        let message = queue[i].clone();
        i += 1;
        if messages
            .iter()
            .any(|m| m.full_name() == message.full_name())
            || foreign(message.package_name())
        {
            continue;
        }
        for field in message.fields() {
            match element_kind(&field) {
                Kind::Message(m) => queue.push(m),
                Kind::Enum(e)
                    if !foreign(e.package_name())
                        && !enums.iter().any(|known| known.full_name() == e.full_name()) =>
                {
                    enums.push(e)
                }
                _ => {}
            }
        }
        messages.push(message);
    }
    (messages, enums)
}

/// A Python name for a proto name: itself, `_` appended where it is a
/// keyword.
fn py_name(name: &str) -> String {
    const KEYWORDS: &[&str] = &[
        "False", "None", "True", "and", "as", "assert", "async", "await", "break", "class",
        "continue", "def", "del", "elif", "else", "except", "finally", "for", "from", "global",
        "if", "import", "in", "is", "lambda", "nonlocal", "not", "or", "pass", "raise", "return",
        "try", "while", "with", "yield",
    ];
    if KEYWORDS.contains(&name) {
        format!("{name}_")
    } else {
        name.to_string()
    }
}

/// `MOVE_ACTION_HIT` of `MoveAction` as `HIT`.
